const b = ($input.first().json.body) || {};
const s = (v) => (typeof v === 'string' ? v.trim() : '');
// Abuse guard (speed bumps for naive bots; the real fix is Turnstile / a WAF).
// 1) The browser always sends Origin; direct scripts usually do not.
// 2) The form sends how long it was open (elapsedMs); bots post instantly.
// Either failing returns the same silent "ok" as the honeypot and stores nothing.
// Add your custom domain to ORIGIN_OK when you have one.
const ORIGIN_OK = /^(http:\/\/localhost:3000|https:\/\/velure-medspa[a-z0-9-]*\.vercel\.app)$/;
const origin = String((($input.first().json.headers) || {}).origin || '');
if (!ORIGIN_OK.test(origin) || !(Number(b.elapsedMs) >= 1000)) return [{ json: { honeypot: true, valid: false } }];

if (s(b.company)) return [{ json: { honeypot: true, valid: false } }];
const email = s(b.email).toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return [{ json: { honeypot: false, valid: false, errors: { email: 'Please enter a valid email' } } }];
return [{ json: { honeypot: false, valid: true, email, today: new Date().toISOString().slice(0, 10) } }];

// Unsubscribe links are signed so nobody can unsubscribe an address they do not own.
// IMPORTANT: replace the secret below with your own long random string, and use the
// SAME value in the "Velure - Subscribe" (Build Welcome) and "Velure - Unsubscribe" (Prepare) nodes.
const UNSUB_SECRET = 'REPLACE_WITH_A_LONG_RANDOM_SECRET';
// Pure-JS HMAC-SHA256 (no require): n8n's Code node blocks built-in modules by default.
const hmacHex = (key, msg) => {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const utf8 = (s) => Array.from(unescape(encodeURIComponent(s)), (c) => c.charCodeAt(0));
  const sha = (bytes) => {
    const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    const l = bytes.length, m = bytes.concat([0x80]);
    while (m.length % 64 !== 56) m.push(0);
    const bits = l * 8;
    for (let i = 7; i >= 0; i--) m.push(i > 3 ? 0 : (bits >>> (i * 8)) & 255);
    const rr = (x, n) => (x >>> n) | (x << (32 - n));
    for (let o = 0; o < m.length; o += 64) {
      const w = [];
      for (let i = 0; i < 16; i++) w[i] = (m[o+i*4] << 24) | (m[o+i*4+1] << 16) | (m[o+i*4+2] << 8) | m[o+i*4+3];
      for (let i = 16; i < 64; i++) {
        const s0 = rr(w[i-15],7) ^ rr(w[i-15],18) ^ (w[i-15] >>> 3);
        const s1 = rr(w[i-2],17) ^ rr(w[i-2],19) ^ (w[i-2] >>> 10);
        w[i] = (w[i-16] + s0 + w[i-7] + s1) | 0;
      }
      let [a,b,c,d,e,f,g,h] = H;
      for (let i = 0; i < 64; i++) {
        const t1 = (h + (rr(e,6) ^ rr(e,11) ^ rr(e,25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
        const t2 = ((rr(a,2) ^ rr(a,13) ^ rr(a,22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
      }
      H[0]=(H[0]+a)|0; H[1]=(H[1]+b)|0; H[2]=(H[2]+c)|0; H[3]=(H[3]+d)|0;
      H[4]=(H[4]+e)|0; H[5]=(H[5]+f)|0; H[6]=(H[6]+g)|0; H[7]=(H[7]+h)|0;
    }
    return H.flatMap((x) => [x >>> 24, (x >>> 16) & 255, (x >>> 8) & 255, x & 255]);
  };
  let k = utf8(key);
  if (k.length > 64) k = sha(k);
  while (k.length < 64) k.push(0);
  const inner = sha(k.map((x) => x ^ 0x36).concat(utf8(msg)));
  const out = sha(k.map((x) => x ^ 0x5c).concat(inner));
  return out.map((x) => x.toString(16).padStart(2, '0')).join('');
};

// Shared Velure email shell (inline styles only — email clients ignore <style> blocks)
